"use client";
import { useRouter } from "next/navigation";
import { PremiumUpgradeDialog } from "@/components/premium-upgrade-dialog";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";

import { useEffect, useId, useRef, useState } from "react";
import { useSendingStatus } from "@/components/sending-status";
import Link from "next/link";
import { Tooltip } from "@/components/ui/Tooltip";
import { Check, Crown, Palette } from "lucide-react";
import {
  chooseAppearance,
  useAppearance,
  useTheme,
  useBlackThemes,
} from "@/components/theme";

const appearances = [
  {
    value: "purple",
    theme: "light",
    name: "Lavender",
    subtitle: "Light",
  },
  {
    value: "purple",
    theme: "dark",
    name: "Nightbloom",
    subtitle: "Dark",
  },
  { value: "vercel", theme: "light", name: "Chalk", subtitle: "Light" },
  {
    value: "vercel",
    theme: "dark",
    name: "Obsidian",
    subtitle: "Dark",
  },
] as const;

export function AppearanceControl() {
  const router = useRouter();
  const [upgradeOpen, setUpgradeOpen] = useState(false);
  const upgrade = usePremiumUpgrade(() => setUpgradeOpen(true));
  const locked = useSendingStatus()?.locked ?? false;
  const blackThemes = useBlackThemes();
  const appearance = useAppearance();
  const theme = useTheme();
  const selectedAppearance = appearances.find(
    (option) => option.value === appearance && option.theme === theme,
  )!;
  const [open, setOpen] = useState(false);
  const [warningOpen, setWarningOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const id = useId();
  const warningId = useId();
  if (locked && open) setOpen(false);
  if (!locked && warningOpen) setWarningOpen(false);
  const close = () => {
    setOpen(false);
    trigger.current?.focus({ preventScroll: true });
  };
  useEffect(() => {
    if (!open && !warningOpen) return;
    if (open)
      root.current
        ?.querySelector<HTMLButtonElement>('[aria-checked="true"]')
        ?.focus();
    const outside = (event: PointerEvent) => {
      if (!root.current?.contains(event.target as Node)) {
        setOpen(false);
        setWarningOpen(false);
      }
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setWarningOpen(false);
    };
    document.addEventListener("pointerdown", outside);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", outside);
      document.removeEventListener("keydown", escape);
    };
  }, [open, warningOpen]);
  return (
    <>
      <div
        ref={root}
        className="appearance-control relative shrink-0"
        onPointerEnter={(event) => {
          if (locked && event.pointerType !== "touch") setWarningOpen(true);
        }}
        onPointerLeave={() => setWarningOpen(false)}
        onBlur={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget as Node)) {
            setOpen(false);
            setWarningOpen(false);
          }
        }}
        onKeyDown=[REDACTED_SECRET]
          if (event.key === "Escape" && warningOpen) {
            event.preventDefault();
            event.stopPropagation();
            setWarningOpen(false);
          }
          if (locked) return;
          if (event.key === "Escape" && open) {
            event.preventDefault();
            event.stopPropagation();
            close();
          }
          if (
            ![
              "ArrowDown",
              "ArrowUp",
              "ArrowLeft",
              "ArrowRight",
              "Home",
              "End",
            ].includes(event.key)
          )
            return;
          event.preventDefault();
          if (!open) {
            setOpen(true);
            return;
          }
          const items = Array.from(
            root.current?.querySelectorAll<HTMLElement>(
              '[role="menuitemradio"], [role="menuitem"]',
            ) ?? [],
          );
          const index = items.indexOf(document.activeElement as HTMLElement);
          items[
            event.key === "Home"
              ? 0
              : event.key === "End"
                ? items.length - 1
                : (index +
                    ({
                      ArrowDown: 2,
                      ArrowUp: -2,
                      ArrowLeft: -1,
                      ArrowRight: 1,
                    }[event.key] ?? 0) +
                    items.length) %
                  items.length
          ]?.focus();
        }}
      >
        <button
          ref={trigger}
          type="button"
          className="appearance-trigger grid place-items-center w-11 h-11 [border:1px_solid_var(--border)] rounded-[8px] [background:var(--card)] text-foreground cursor-pointer css-hover:bg-surface aria-disabled:opacity-[0.5] aria-disabled:cursor-not-allowed focus-visible:[outline:2px_solid_var(--ring)] focus-visible:[outline-offset:3px]"
          aria-label="Choose appearance"
          title={
            locked
              ? undefined
              : `Theme: ${selectedAppearance.name} (${selectedAppearance.subtitle})`
          }
          aria-disabled={locked}
          aria-describedby={warningOpen ? warningId : undefined}
          aria-haspopup="menu"
          aria-expanded={open}
          aria-controls={open ? id : undefined}
          onClick={() => {
            if (locked) return;
            if (open) close();
            else setOpen(true);
          }}
        >
          <Palette size={18} aria-hidden="true" />
        </button>
        {warningOpen && (
          <div
            id={warningId}
            role="tooltip"
            className="absolute top-full right-0 z-[150] w-[min(300px,_calc(100vw_-_32px))] pt-2.5"
          >
            <div className="rounded-lg border border-border bg-card p-3 text-[13px] leading-normal text-foreground shadow-[0_12px_40px_var(--color-appearance-control-box-shadow-1)]">
              Theme changes are unavailable while emails are being sent. Please
              wait until sending finishes.
            </div>
          </div>
        )}
        {open && (
          <div
            id={id}
            role="menu"
            aria-label="Appearance"
            className="appearance-menu absolute [top:calc(100%_+_10px)] right-0 z-[150] w-[min(440px,_calc(100vw_-_32px))] max-h-[calc(100dvh_-_100px)] overflow-y-auto [border:1px_solid_var(--border)] rounded-[20px] [background:var(--card)] text-foreground p-5 shadow-[0_12px_40px_var(--color-appearance-control-box-shadow-1)] [@media(max-width:_480px)]:fixed [@media(max-width:_480px)]:top-20 [@media(max-width:_480px)]:right-4 [@media(max-width:_480px)]:max-h-[calc(100dvh_-_96px)] [@media(max-width:_480px)]:p-4"
          >
            <p className="appearance-label m-0 text-[18px] font-bold leading-[1.4]">
              Theme
            </p>
            <p className="appearance-description [margin:4px_0_20px] text-muted-foreground text-[13px] leading-normal">
              Pick the mood for your workspace.
            </p>
            <div className="appearance-grid grid grid-cols-[repeat(2,_minmax(0,_1fr))] gap-3">
              {appearances.map(({ value, theme: mode, name, subtitle }) => {
                const premiumLocked = value === "vercel" && !blackThemes;
                const selected = appearance === value && theme === mode;
                const option = (
                  <button
                    type="button"
                    key={`${value}-${mode}`}
                    role="menuitemradio"
                    className="appearance-option block size-full min-w-0 p-2.5 border-2 border-border! rounded-[16px]! bg-card! cursor-pointer text-left text-foreground! css-hover:bg-surface! css-hover:border-muted-foreground! aria-checked:border-ring! aria-checked:bg-[color-mix(in_srgb,var(--ring)_7%,var(--card))]! css-hover:aria-checked:border-ring! css-hover:aria-checked:bg-[color-mix(in_srgb,var(--ring)_7%,var(--card))]! focus-visible:outline-2! focus-visible:outline-ring! focus-visible:outline-offset-3!"
                    aria-checked={selected}
                    aria-label={
                      premiumLocked ? `${name} Premium ${subtitle}` : undefined
                    }
                    disabled={locked}
                    onClick={() => {
                      if (locked) return;
                      if (premiumLocked) {
                        upgrade({
                          feature: "themes",
                          trigger: trigger.current,
                        });
                        setOpen(false);
                        return;
                      }
                      chooseAppearance(value, mode);
                      close();
                    }}
                  >
                    <span
                      className={`appearance-preview relative block w-full [aspect-ratio:1.8] min-h-24.5 py-3.5 px-3 [border:1px_solid_var(--color-appearance-control-border-5)] rounded-[8px] [background:var(--preview-bg)] appearance-preview-${value}-${mode}`}
                      aria-hidden="true"
                    >
                      <span className="appearance-preview-nav flex items-center gap-2 mb-3">
                        <i className="size-2.5 rounded-full bg-[var(--preview-accent)]" />
                        <span className="flex gap-1">
                          <i className="w-9 h-[3px] rounded-[3px] bg-[var(--preview-ink)]" />
                        </span>
                      </span>
                      <span className="appearance-preview-card grid gap-[7px]">
                        <i className="w-[84%] h-[5px] rounded-[4px] bg-[var(--preview-ink)]" />
                        <i className="w-[60%] h-1 rounded-[4px] bg-[var(--preview-ink)]" />
                        <b className="w-[32%] h-2.5 mt-0.5 rounded-full bg-[var(--preview-accent)]" />
                      </span>
                      {premiumLocked && (
                        <span className="appearance-check appearance-lock absolute top-2 right-2 grid place-items-center w-6 h-6 rounded-full border border-[color-mix(in_srgb,var(--premium-icon)_24%,var(--card))] bg-card text-[var(--premium-icon)] shadow-[0_0_0_2px_var(--preview-bg)]">
                          <Crown
                            size={14}
                            className="premium-icon"
                            aria-hidden="true"
                          />
                        </span>
                      )}
                      {selected && (
                        <span className="appearance-check absolute top-2 right-2 grid place-items-center w-5 h-5 rounded-[50%] [background:var(--foreground)] text-card shadow-[0_0_0_2px_var(--preview-bg)]">
                          <Check size={13} />
                        </span>
                      )}
                    </span>
                    <span className="appearance-option-label block mt-3 text-[14px] font-bold leading-normal">
                      {name}
                      {premiumLocked && (
                        <span className="appearance-premium inline-block ml-1.5 py-[1px] px-[5px] border border-[color-mix(in_srgb,var(--premium-icon)_24%,var(--card))] rounded-[5px] bg-[color-mix(in_srgb,var(--premium-icon)_7%,var(--card))] text-[10px] font-medium align-middle text-[var(--premium-icon)]">
                          Premium
                        </span>
                      )}
                    </span>
                    <span className="appearance-option-subtitle block mt-0.5 text-muted-foreground text-[12px] leading-normal">
                      {subtitle}
                    </span>
                  </button>
                );
                return premiumLocked ? (
                  <Tooltip
                    key={`${value}-${mode}`}
                    content="Upgrade to Premium to unlock this theme"
                    placement="bottom"
                    maxWidth={220}
                    triggerClassName="block min-w-0"
                  >
                    {option}
                  </Tooltip>
                ) : (
                  option
                );
              })}
            </div>
            {!blackThemes && (
              <Link
                className="appearance-upgrade relative isolate overflow-hidden block mt-4 py-2 px-0 text-[13px] font-bold text-foreground underline focus-visible:[outline:2px_solid_var(--ring)] focus-visible:[outline-offset:3px]"
                role="menuitem"
                href="/usage"
                onClick={() => setOpen(false)}
              >
                Upgrade to Premium
              </Link>
            )}
          </div>
        )}
      </div>
      {upgradeOpen && (
        <PremiumUpgradeDialog
          reason="feature"
          feature="themes"
          returnFocusRef={trigger}
          onClose={() => setUpgradeOpen(false)}
          onUpgrade={() => router.push("/usage")}
        />
      )}
    </>
  );
}
